def link_existing_jobs(apps, schema_editor):
    """Attach jobs created before upload batches were linked.

    Older jobs use the ``upload:<batch uuid>:<conversation id>`` request key.
    Jobs keyed by a conversation digest cannot be resolved without the digest
    map, so they are left unlinked rather than guessed.
    """

    AnalysisJob = apps.get_model("chat_analysis", "AnalysisJob")
    UploadBatch = apps.get_model("chat_ingestion", "UploadBatch")
    batches = {str(batch.uuid): batch for batch in UploadBatch.objects.all()}
    for job in AnalysisJob.objects.all().iterator():
        parts = (job.request_key or "").split(":")
        if len(parts) < 2 or parts[0] != "upload":
            continue
        batch = batches.get(parts[1])
        if batch is not None:
            job.upload_batches.add(batch)

